import java.nio.file.*;import java.lang.reflect.*;import java.util.*;import se.krka.kahlua.vm.*;import zombie.Lua.LuaManager;import zombie.iso.*;import zombie.iso.objects.*;import zombie.iso.sprite.*;
public final class ElectricalServiceNativeProbe {
 static zombie.characters.IsoPlayer body;static IsoGenerator generator;static IsoStove stove;static Path unit,out;static List<IsoObject> parts=new ArrayList<>();
 static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static void expose(Class<?>c){LuaManager.exposer.setExposed(c);LuaManager.exposer.exposeLikeJava(c,LuaManager.env);LuaManager.exposer.exposeLikeJavaRecursively(c,LuaManager.env);}
 static void load(Path p)throws Exception{String source=Files.readString(p);String control=System.getProperty("sao.d6.control","none");if(control.equals("omit-native-toggle")&&p.getFileName().toString().equals("ISToggleStoveAction.lua")){String anchor="self.object:Toggle()";if(source.indexOf(anchor)!=source.lastIndexOf(anchor)||!source.contains(anchor))throw new AssertionError("toggle source anchor");source=source.replace(anchor,"-- omitted original native toggle");Files.writeString(out.resolve("omitted-ISToggleStoveAction.lua"),source);}if(control.equals("restore-fuel-revoke")&&p.getFileName().toString().equals("SAO_ElectricalService.lua")){String anchor="return after.atHours>=before.atHours";if(source.indexOf(anchor)!=source.lastIndexOf(anchor)||!source.contains(anchor))throw new AssertionError("measurement source anchor");source=source.replace(anchor,"return after.atHours>=before.atHours and after.fuel==before.fuel");Files.writeString(out.resolve("restored-fuel-revoke-SAO_ElectricalService.lua"),source);}var chunk=se.krka.kahlua.luaj.compiler.LuaCompiler.loadstring(source,p.toString(),LuaManager.env);var r=LuaManager.thread.pcall(chunk,new Object[0]);if(!Boolean.TRUE.equals(r[0]))throw new AssertionError(p+" "+Arrays.toString(r));}
 static void nativeSprites(Path game)throws Exception{
  boolean server=zombie.network.GameServer.server,gui=zombie.network.GameServer.guiCommandline;try{zombie.network.GameServer.server=true;zombie.network.GameServer.guiCommandline=false;IsoWorld.instance.LoadTileDefinitionsPropertyStrings(IsoSpriteManager.instance,game.resolve("media/newtiledefinitions.tiles").toString(),1);var m=IsoWorld.class.getDeclaredMethod("GenerateTilePropertyLookupTables");m.setAccessible(true);m.invoke(IsoWorld.instance);IsoWorld.instance.LoadTileDefinitions(IsoSpriteManager.instance,game.resolve("media/newtiledefinitions.tiles").toString(),1);}finally{zombie.network.GameServer.server=server;zombie.network.GameServer.guiCommandline=gui;}
 }
 static Object nativeCall(LuaCallFrame f,int n)throws Exception{
  String op=(String)f.get(0);switch(op){
   case "hour":{double before=zombie.GameTime.getInstance().getWorldAgeHours();var time=zombie.GameTime.getInstance();float current=time.getTimeOfDay(),next=current+1;if(next>=24)next-=24;if(current<7&&next>=7)time.setNightsSurvived(time.getNightsSurvived()+1);time.setTimeOfDay(next);double elapsed=time.getWorldAgeHours()-before;if(elapsed!=1)throw new AssertionError("native county-hour step "+elapsed);generator.update();return f.push(elapsed);}
   case "update":generator.update();return f.push(true);
   case "bill":{IsoGenerator.updateSurroundingNow();return f.push((double)generator.getTotalPowerUsing());}
   case "move":{int x=((Double)f.get(1)).intValue(),y=((Double)f.get(2)).intValue();var q=body.getCell().getGridSquare(x,y,0);body.getCurrentSquare().getMovingObjects().remove(body);body.setX(x+.5f);body.setY(y+.5f);body.setZ(0);body.setCurrent(q);body.setSquare(q);q.getMovingObjects().add(body);return f.push(true);}
   case "start":{var a=(zombie.characters.CharacterTimedActions.LuaTimedActionNew)f.get(1);for(int step=0;step<100&&!a.isStarted();step++){a.waitToStart();var anim=body.getAnimationPlayer();if(anim!=null){var forward=body.getForwardDirection();anim.setTargetAngle(zombie.core.skinnedmodel.animation.AnimationPlayer.calculateAnimPlayerAngle(forward.x,forward.y));anim.setAngleToTarget();}}System.out.println("NATIVE_ACTION_START started="+a.isStarted()+" forceComplete="+a.isForceComplete());return f.push(a.isStarted());}
   case "finish":{var a=(zombie.characters.CharacterTimedActions.LuaTimedActionNew)f.get(1);int step=0;while(a.getJobDelta()<1&&a.isStarted()&&!a.forceStop&&step<1000){a.update();step++;}System.out.println("NATIVE_ACTION_END frames="+step+" finished="+a.finished()+" forceComplete="+a.isForceComplete()+" forceStop="+a.forceStop);if(!a.finished()||a.isForceComplete()||a.forceStop)return f.push(false);a.perform();a.complete();body.getCharacterActions().remove(a);return f.push(true);}
   case "facts":{var t=LuaManager.platform.newTable();t.rawset("fuel",(double)generator.getFuel());t.rawset("condition",(double)generator.getCondition());t.rawset("bill",(double)generator.getTotalPowerUsing());t.rawset("base",generator.getBasePowerConsumption());t.rawset("fuelScale",zombie.SandboxOptions.instance.generatorFuelConsumption.getValue());t.rawset("itemsPowered",generator.getItemsPowered().toString());t.rawset("active",generator.isActivated());t.rawset("connected",generator.isConnected());t.rawset("hours",zombie.GameTime.getInstance().getWorldAgeHours());return f.push(t);}
   case "dump":{Files.writeString(out.resolve("measurements.json"),json(f.get(1)));return 0;}
   default:throw new AssertionError(op);
  }
 }
 static String json(Object v){if(v==null)return"null";if(v instanceof String s)return"\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof KahluaTable t){var e=new ArrayList<String>();var it=t.iterator();while(it.advance())e.add(json(String.valueOf(it.getKey()))+":"+json(it.getValue()));Collections.sort(e);return"{"+String.join(",",e)+"}";}throw new AssertionError(v);}
 public static void main(String[]args)throws Exception{
  Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});
  Path game=Path.of(args[0]);unit=Path.of(args[1]);out=Path.of(args[2]);zombie.core.Core.gameSaveWorld="isolated-d6-native-service";
  var cell=GeneratorNativeProbe.initialise(game);var shell=(com.sao.engine.SAOIsoPlayerShell)field(GeneratorNativeProbe.class,"body").get(null);var old=(IsoObject)field(GeneratorNativeProbe.class,"consumer").get(null);old.getSquare().getChunk().removeObjectPoweredByGenerator(old);old.getSquare().getObjects().remove(old);
  var platform=new se.krka.kahlua.j2se.J2SEPlatform();LuaManager.platform=platform;LuaManager.env=platform.newEnvironment();LuaManager.thread=new KahluaThread(platform,LuaManager.env);LuaManager.thread.debugOwnerThread=Thread.currentThread();LuaManager.converterManager=new se.krka.kahlua.converter.KahluaConverterManager();zombie.Lua.KahluaNumberConverter.install(LuaManager.converterManager);LuaManager.caller=new se.krka.kahlua.integration.LuaCaller(LuaManager.converterManager);zombie.ui.UIManager.defaultthread=LuaManager.thread;LuaManager.exposer=new LuaManager.Exposer(LuaManager.converterManager,platform,LuaManager.env);zombie.Lua.LuaEventManager.Reset();zombie.Lua.LuaEventManager.register(platform,LuaManager.env);LuaManager.exposer.exposeAll();
  body=new zombie.characters.IsoPlayer(cell,shell.getDescriptor(),14,20,0);body.setECSComponent(new zombie.characters.component.AIComponent());field(zombie.characters.IsoGameCharacter.class,"animPlayer").set(body,shell.getAnimationPlayer());var q=cell.getGridSquare(14,20,0);body.setX(14.5f);body.setY(20.5f);body.setZ(0);body.setCurrent(q);body.setSquare(q);q.getMovingObjects().add(body);cell.getObjectList().add(body);zombie.characters.IsoPlayer.setLocalPlayer(0,body);
  nativeSprites(game);
  var choices=IsoSpriteManager.instance.namedMap.values().stream().filter(p->p.name!=null&&p.name.startsWith("appliances_cooking_")&&p.getSpriteGrid()!=null&&p.getSpriteGrid().getSpriteCount()>1).sorted(Comparator.comparing(p->p.name)).toList();if(choices.isEmpty())throw new AssertionError("installed multipart stove unavailable");var anchor=choices.get(0).getSpriteGrid().getAnchorSprite();var grid=anchor.getSpriteGrid();
  for(int i=0;i<grid.getSpriteCount();i++){var sprite=grid.getSpriteFromIndex(i);int x=14+grid.getSpriteGridPosX(sprite),y=20+grid.getSpriteGridPosY(sprite);var sq=cell.getGridSquare(x,y,0);sq.room=new zombie.iso.areas.IsoRoom();sq.roomId=1;var o=new IsoStove(cell,sq,sprite);o.setContainer(new zombie.inventory.ItemContainer("stove",sq,o));sq.getObjects().add(o);sq.getChunk().addObjectPoweredByGenerator(o);parts.add(o);if(sprite==anchor)stove=o;}
  if(stove==null)throw new AssertionError("installed stove anchor");stove.setActivated(true);System.out.println("NATIVE_MULTIPART sprite="+anchor.name+" count="+parts.size()+" group="+stove.getSpriteGridObjectsIncludingSelf(new ArrayList<>()).size());
  zombie.GameTime.getInstance().setNightsSurvived(10);generator=GeneratorNativeProbe.generator("Base.Generator",10,20);generator.setFuel(10);generator.setCondition(100);generator.setConnected(true);generator.setActivated(true);stove.setActivated(true);IsoGenerator.updateGenerator(stove.getSquare());IsoGenerator.updateSurroundingNow();System.out.println("NATIVE_BOOTSTRAP human="+body.isLocalPlayer()+" inWorld="+body.isExistInTheWorld()+" fuel="+generator.getFuel()+" rate="+generator.getTotalPowerUsing()+" items="+generator.getItemsPowered());
  for(Class<?>c:List.of(IsoStove.class,IsoGenerator.class,IsoObject.class,IsoGridSquare.class,IsoCell.class,IsoWorld.class,zombie.characters.IsoPlayer.class,zombie.characters.IsoGameCharacter.class,zombie.characters.CharacterTimedActions.LuaTimedActionNew.class,zombie.characters.CharacterTimedActions.BaseAction.class,zombie.characters.Stats.class,zombie.characters.CharacterStat.class,zombie.inventory.ItemContainer.class,com.sao.bridge.SAOBridge.class,zombie.GameTime.class,zombie.audio.BaseSoundEmitter.class,zombie.characters.BaseCharacterSoundEmitter.class,zombie.util.list.PZArrayList.class,ArrayList.class,List.class,java.util.Stack.class,java.util.Vector.class,zombie.characters.BodyDamage.Metabolics.class))expose(c);
  LuaManager.env.rawset("body",body);LuaManager.env.rawset("generator",generator);LuaManager.env.rawset("consumer",stove);LuaManager.env.rawset("SAOJavaBridge",com.sao.bridge.SAOBridge.INSTANCE);LuaManager.env.rawset("__world",IsoWorld.instance);
  LuaManager.env.rawset("__load",(JavaFunction)(f,n)->{try{load(Path.of((String)f.get(0)));return 0;}catch(Exception e){throw new RuntimeException(e);}});
  LuaManager.env.rawset("__coverage",(JavaFunction)(f,n)->f.push(IsoGenerator.isPoweringSquare(((Double)f.get(0)).intValue(),((Double)f.get(1)).intValue(),((Double)f.get(2)).intValue(),((Double)f.get(3)).intValue(),((Double)f.get(4)).intValue(),((Double)f.get(5)).intValue())));
  LuaManager.env.rawset("CONTROL",System.getProperty("sao.d6.control","none"));LuaManager.env.rawset("__native",(JavaFunction)(f,n)->{try{return (Integer)nativeCall(f,n);}catch(Exception e){throw new RuntimeException(e);}});LuaManager.env.rawset("__game",game.toString().replace('\\','/'));LuaManager.env.rawset("__unit",unit.toString().replace('\\','/'));LuaManager.env.rawset("print",(JavaFunction)(f,n)->{for(int i=0;i<n;i++)System.out.print((i==0?"":"\t")+f.get(i));System.out.println();return 0;});
  load(unit.resolve("electrical_ports.lua"));load(unit.resolve("electrical_cases.lua"));System.exit(0);
 }
}
